const item = $input.first();
if (item.error) {
  console.log('arXiv fetch error:', item.error.message || 'unknown');
  return [{ json: { _skip: true, source_id: '_error_arxiv', content: '' } }];
}
const raw = item.json;
const body = typeof raw === 'string' ? raw : (raw.body || raw.data || raw.text || '');
if (!body || body.length < 100) {
  console.log('arXiv empty body type=' + typeof raw + ' keys=' + (raw && typeof raw==='object' ? Object.keys(raw).join(',') : 'N/A'));
  return [{ json: { _skip: true, source_id: '_empty_arxiv', content: '' } }];
}
const entries = body.match(/<entry>[\s\S]*?<\/entry>/g) || [];
const docs = [];
for (const entry of entries) {
  const tm = entry.match(/<title>([\s\S]*?)<\/title>/);
  const title = tm ? tm[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim() : '';
  const sm = entry.match(/<summary>([\s\S]*?)<\/summary>/);
  const abstract = sm ? sm[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim() : '';
  const im = entry.match(/<id>([\s\S]*?)<\/id>/);
  const idFull = im ? im[1].trim() : '';
  if (!title || !abstract || abstract.length < 50) continue;
  const arxivId = (idFull.split('/abs/')[1] || idFull).replace(/\s/g, '');
  const content = 'Title: ' + title + '\n\nAbstract: ' + abstract + '\n\nSource: arXiv | ID: ' + arxivId;
  const source_id = 'arxiv_' + arxivId.replace(/[^a-zA-Z0-9.]/g, '_').substring(0, 60);
  docs.push({ content, source_id, pdf_url: 'https://arxiv.org/pdf/' + arxivId, filename: source_id + '.pdf', chunk_size: 1000, chunk_overlap: 100, prefer_pdf: true, pdf_ingest_mode: 'deferred' });
}
console.log('arXiv parsed:', docs.length, 'papers from', entries.length, 'entries');
if (docs.length === 0) return [{ json: { _skip: true, source_id: '_empty_arxiv', content: '' } }];
return docs.map(d => ({ json: d }));

const item = $input.first();
if (item.error) {
  console.log('S2 fetch error:', item.error.message || 'unknown');
  return [{ json: { _skip: true, source_id: '_error_s2', content: '' } }];
}
const raw = item.json;
let s2Data;
if (typeof raw === 'string') {
  try { s2Data = JSON.parse(raw); } catch(e) { console.log('S2 parse fail:', e.message); s2Data = { data: [] }; }
} else if (raw && typeof raw === 'object') {
  const bodyStr = raw.body || raw.data || raw.text;
  if (typeof bodyStr === 'string') {
    try { s2Data = JSON.parse(bodyStr); } catch(e) { s2Data = { data: [] }; }
  } else if (bodyStr && typeof bodyStr === 'object' && Array.isArray(bodyStr.data)) {
    s2Data = bodyStr;
  } else {
    s2Data = raw;
  }
} else {
  s2Data = { data: [] };
}
const papers = s2Data.data || [];
const docs = [];
for (const paper of papers) {
  if (!paper.title || !paper.abstract || paper.abstract.length < 50) continue;
  const authorsStr = (paper.authors || []).slice(0, 5).map(function(a) { return a.name; }).join(', ');
  const content = 'Title: ' + paper.title + '\n\nAbstract: ' + paper.abstract + '\n\nSource: Semantic Scholar | Year: ' + (paper.year || 'N/A') + ' | Citations: ' + (paper.citationCount || 0) + ' | Authors: ' + authorsStr;
  const source_id = 'ss_' + (paper.paperId || '').substring(0, 40).replace(/[^a-zA-Z0-9]/g, '_');
  const pdf_url = paper.openAccessPdf && paper.openAccessPdf.url ? paper.openAccessPdf.url : '';
  docs.push({ content, source_id, pdf_url, filename: source_id + '.pdf', chunk_size: 1000, chunk_overlap: 100, prefer_pdf: !!pdf_url, pdf_ingest_mode: 'deferred' });
}
console.log('S2 parsed:', docs.length, 'papers from', papers.length, 'results');
if (docs.length === 0) return [{ json: { _skip: true, source_id: '_empty_s2', content: '' } }];
return docs.map(d => ({ json: d }));

const item = $input.first();
if (item.error) {
  console.log('KD fetch error:', item.error.message || 'unknown');
  return [{ json: { _skip: true, source_id: '_error_kd', content: '' } }];
}
const raw = item.json;
const body = typeof raw === 'string' ? raw : (raw.body || raw.data || raw.text || '');
if (!body || body.length < 100) {
  console.log('KD empty body type=' + typeof raw);
  return [{ json: { _skip: true, source_id: '_empty_kd', content: '' } }];
}
const items = body.match(/<item>[\s\S]*?<\/item>/g) || [];
const docs = [];
for (const it of items) {
  const tm = it.match(/<title>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/title>/);
  const title = tm ? tm[1].trim() : '';
  const dm = it.match(/<description>(?:<!\[CDATA\[)?([\s\S]*?)(?:\]\]>)?<\/description>/);
  const desc = dm ? dm[1].replace(/<[^>]+>/g, '').replace(/\s+/g, ' ').trim() : '';
  const lm = it.match(/<link>([\s\S]*?)<\/link>/);
  const link = lm ? lm[1].trim() : '';
  if (!title || !desc || desc.length < 30) continue;
  const content = 'Title: ' + title + '\n\nSummary: ' + desc + '\n\nSource: KDnuggets | URL: ' + link;
  const source_id = 'kd_' + title.toLowerCase().replace(/[^a-z0-9]/g, '_').substring(0, 50);
  docs.push({ content, source_id, chunk_size: 1000, chunk_overlap: 100 });
}
console.log('KDnuggets parsed:', docs.length, 'articles from', items.length, 'items');
if (docs.length === 0) return [{ json: { _skip: true, source_id: '_empty_kd', content: '' } }];
return docs.map(d => ({ json: d }));

const r = $input.first().json;
if (r && (r.chunks_created !== undefined || r.status === 'ok')) {
  console.log('Ingested ok — chunks:', r.chunks_created || 0, '| source:', r.source_id || '');
} else {
  console.log('Ingest error:', JSON.stringify(r).substring(0, 200));
}
return [{ json: { done: true, source_id: r && r.source_id || '', chunks: r && r.chunks_created || 0 } }];

const ts = new Date().toISOString();
console.log('[' + ts + '] Doc ingested ok');
return [{ json: { timestamp: ts, status: 'ok' } }];
